<div class="page-head"><div><span class="eyebrow">CATALOGUE</span><h1>Produits & stocks</h1><p class="muted">Gérez vos articles, prix et niveaux de stock.</p></div><a class="btn primary" href="<?= e(url('/products/create')) ?>">＋ Nouveau produit</a></div><section class="panel"><div class="panel-head"><h2><?= count($rows) ?> produit(s)</h2><a href="<?= e(url('/products/export')) ?>">↓ Exporter CSV</a></div><form class="import" method="post" action="<?= e(url('/products/import')) ?>" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn secondary">Importer CSV</button><small>Colonnes : sku;name;category;buy_price;sell_price;stock;alert_stock</small></form><div class="table-wrap"><table><thead><tr><th>Référence</th><th>Produit</th><th>Catégorie</th><th>Prix de vente</th><th>Stock</th><th>État</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['sku']) ?></td><td><b><?= e($r['name']) ?></b></td><td><?= e($r['category']) ?></td><td><?= money($r['sell_price']) ?></td><td><?= (int)$r['stock'] ?></td><td><?= $r['stock']<=$r['alert_stock']?'<span class="pill red">Stock faible</span>':'<span class="pill green">Disponible</span>' ?></td><td><form method="post" action="<?= e(url('/products/delete')) ?>" onsubmit="return confirm('Supprimer ce produit ?')"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="icon-btn">×</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="empty">Votre catalogue est vide.</div><?php endif; ?></div></section>